    "interactive": { pt: "`TRUE` converte o resultado do ggplot2 em um widget interativo do plotly. Padrão `FALSE`.", en: "`TRUE` converts the ggplot2 output into an interactive plotly widget. Default `FALSE`.", es: "`TRUE` convierte el resultado de ggplot2 en un widget interactivo de plotly. Predeterminado `FALSE`." },
    "base_size": { pt: "Tamanho base da fonte para o ggplot2. Padrão `12`.", en: "Base font size for ggplot2. Default `12`.", es: "Tamaño base de la fuente para ggplot2. Predeterminado `12`." },
    "save_plot": { pt: "Caminho do arquivo para salvar o gráfico (PNG/PDF para gráficos estáticos; HTML para interativos), ou `NULL`.", en: "File path to save the plot (PNG/PDF for static plots; HTML for interactive), or `NULL`.", es: "Ruta del archivo para guardar el gráfico (PNG/PDF para gráficos estáticos; HTML para interactivos), o `NULL`." },
