    "exposure_at": { pt: "Valor de exposição usado como ponto focal do gráfico `\"lag\"`. Quando `NULL` (padrão), usa-se o percentil 75 da exposição no lag 0.", en: "Exposure value used as the focal point for the `\"lag\"` plot. When `NULL` (default), the 75th percentile of lag-0 exposure is used.", es: "Valor de exposición usado como punto focal del gráfico `\"lag\"`. Cuando es `NULL` (predeterminado), se usa el percentil 75 de la exposición en el lag 0." },
    "lags_at": { pt: "Tempos de defasagem (lag) mostrados no gráfico `\"slice\"`. O padrão é `c(0L, 3L, 7L, 14L, 21L)`, ajustado automaticamente até `lag_max`.", en: "Lag times shown in the `\"slice\"` plot. Default is `c(0L, 3L, 7L, 14L, 21L)`, automatically clipped to `lag_max`.", es: "Tiempos de rezago (lag) mostrados en el gráfico `\"slice\"`. El valor predeterminado es `c(0L, 3L, 7L, 14L, 21L)`, recortado automáticamente hasta `lag_max`." },
    "pred_at": { pt: "Probabilidades de quantil (entre 0 e 1) nas quais reportar o risco relativo acumulado na tabela estatística. O padrão é `c(0.05, 0.10, 0.25, 0.50, 0.75, 0.90, 0.95, 0.99)`.", en: "Quantile probabilities (between 0 and 1) at which to report the cumulative relative risk in the statistical table. Default is `c(0.05, 0.10, 0.25, 0.50, 0.75, 0.90, 0.95, 0.99)`.", es: "Probabilidades de cuantil (entre 0 y 1) en las que reportar el riesgo relativo acumulado en la tabla estadística. El valor predeterminado es `c(0.05, 0.10, 0.25, 0.50, 0.75, 0.90, 0.95, 0.99)`." },
    "interactive": { pt: "Defina como `TRUE` para um gráfico interativo plotly (visualização plotly em 3-D para `\"surface\"`); `FALSE` (padrão) gera um gráfico estático.", en: "Set to `TRUE` for an interactive plotly chart (a 3-D plotly view for `\"surface\"`); `FALSE` (default) gives a static chart.", es: "Defina como `TRUE` para un gráfico interactivo plotly (vista plotly en 3-D para `\"surface\"`); `FALSE` (predeterminado) genera un gráfico estático." },
    "color_palette": { pt: "Nome de uma paleta de cores ggsci. O padrão é `\"npg\"`. Outras opções úteis são `\"lancet\"`, `\"jama\"`, `\"nejm\"` e `\"aaas\"`.", en: "Name of a ggsci color palette. Default is `\"npg\"`. Other useful options are `\"lancet\"`, `\"jama\"`, `\"nejm\"`, and `\"aaas\"`.", es: "Nombre de una paleta de colores ggsci. El valor predeterminado es `\"npg\"`. Otras opciones útiles son `\"lancet\"`, `\"jama\"`, `\"nejm\"` y `\"aaas\"`." },
